<?php $staff=$me['role']==='admin';$tid=(int)$ticket['id'];$replyCount=(int)$a->db->value('SELECT COUNT(*) FROM cy_support_replies WHERE ticket_id=?',[$tid]);$replyPage=$supportPage??1; ?>
<section class="panel commerce-panel"><div class="row between wrap"><div><span class="eyebrow">#<?= $tid ?> / <?= t($ticket['status']) ?></span><h2><?= e($ticket['subject']) ?></h2><p class="hint"><?= e($ticket['display_name']) ?> &middot; <?= dt((int)$ticket['created_at'],'Y-m-d H:i') ?><?php if($ticket['order_id']): ?> &middot; <?= t('Order ID') ?> #<?= (int)$ticket['order_id'] ?><?php endif ?></p></div><span class="pill"><?= t($ticket['priority']) ?></span></div>
<div class="support-thread"><?php foreach($a->support->replies($me,$tid,$replyPage) as $reply): ?><article class="support-message <?= $reply['role']==='admin'?'staff':'' ?>"><header><strong><?= e($reply['display_name']) ?></strong><time><?= dt((int)$reply['created_at'],'Y-m-d H:i') ?></time></header><div class="prose"><?= \Chengyu\Core\Markdown::render($reply['body']) ?></div></article><?php endforeach ?></div>
<?php partial('pagination',array_merge(['pagination'=>['page'=>$replyPage,'pages'=>max(1,(int)ceil($replyCount/50))]],$staff?['tab'=>'support']:['route'=>'support'])); ?>
<?php if($ticket['status']!=='closed'): ?><?= form_start('support_reply','','',false).hidden('ticket_id',$tid).hidden('revision',$ticket['revision']).hidden('request_key',bin2hex(random_bytes(16))) ?>
<?php if($staff): ?><label class="field"><span><?= t('Reply template') ?></span><select data-reply-template><option value=""><?= t('Choose a template') ?></option><?php foreach($a->db->all('SELECT id,title,body FROM cy_support_templates WHERE active=1 ORDER BY title,id') as $template): ?><option value="<?= e($template['body']) ?>"><?= e($template['title']) ?></option><?php endforeach ?></select></label><?php endif ?>
<?php field('body','Your reply','','textarea',['required'=>'required','maxlength'=>'4000','data-support-body'=>'1']);button('Send reply','','message'); ?></form><?php endif ?>
<details class="commerce-details"><summary><?= t('Ticket status') ?></summary><?= form_start('support_status','','',false).hidden('ticket_id',$tid).hidden('revision',$ticket['revision']) ?><?php select_field('status','Status',options($staff?\Chengyu\Services\SupportDesk::STATES:['open','closed']),$ticket['status']);if($staff){select_field('priority','Priority',options(['normal','urgent']),$ticket['priority']);}button('Update ticket','secondary','check'); ?></form></details></section>
